#!/usr/bin/env node
/**
 * Extract page-level bundle sizes from the existing Next.js build output.
 *
 * This script complements the existing scripts/check-bundle-size.js by:
 *   1. Reading the .bundle-report.json generated by check-bundle-size.js
 *   2. Walking .next/static/chunks/ for raw file sizes
 *   3. Categorizing chunks by page name
 *   4. Writing bundle-sizes.json for PR comment generation
 *
 * Input:
 *   - .bundle-report.json  (from scripts/check-bundle-size.js, generated during build)
 *   - .next/static/chunks/  (raw build output)
 *
 * Output:
 *   - bundle-sizes.json     (simplified page-sizes map for the workflow)
 */

const fs = require("fs");
const path = require("path");

const BUNDLE_REPORT =
  process.env.BUNDLE_REPORT ||
  path.join(process.cwd(), ".bundle-report.json");
const NEXT_STATIC_CHUNKS = path.join(
  process.cwd(),
  ".next",
  "static",
  "chunks",
);
const NEXT_ANALYZE_DIR =
  process.env.NEXT_ANALYZE_DIR ||
  path.join(process.cwd(), ".next", "analyze");
const OUTPUT_DIR = process.env.OUTPUT_DIR || ".";

// ----- Helpers -----------------------------------------------------------

function isPageChunk(name) {
  // Next.js page chunks typically follow:
  //   chunks/pages/index-<hash>.js
  //   chunks/pages/_app-<hash>.js
  //   pages/index-<hash>.js  (flat structure in some configs)
  return (
    name.startsWith("pages/") ||
    name.startsWith("chunks/pages/") ||
    name === "_app.js" ||
    name.startsWith("_app-") ||
    name.startsWith("_error-") ||
    name.startsWith("_document-")
  );
}

function isFrameworkChunk(name) {
  return (
    name.startsWith("webpack-") ||
    name.startsWith("framework-") ||
    name.startsWith("_buildManifest") ||
    name.startsWith("_ssgManifest") ||
    name.startsWith("_middlewareManifest") ||
    name.startsWith("react-refresh") ||
    name.includes("hot-update")
  );
}

function extractPageName(chunkName) {
  // Convert chunk filenames to page identifiers:
  //   pages/index-abc123.js       -> pages/index
  //   chunks/pages/index-abc123.js -> pages/index
  //   _app-abc123.js              -> _app

  let name = path.basename(chunkName, ".js");

  // Strip content hash (hex suffix)
  name = name.replace(/-[a-f0-9]{8,20}$/i, "");
  // Strip chunks/ prefix
  name = name.replace(/^chunks\//, "");

  return name;
}

// ----- Main --------------------------------------------------------------

function main() {
  // 1. Read existing bundle report from check-bundle-size.js
  let bundleReport = null;
  if (fs.existsSync(BUNDLE_REPORT)) {
    try {
      bundleReport = JSON.parse(fs.readFileSync(BUNDLE_REPORT, "utf8"));
      console.log("Read bundle report from:", BUNDLE_REPORT);
    } catch (err) {
      console.warn("Could not parse bundle report:", err.message);
    }
  } else {
    console.warn("No bundle report found at:", BUNDLE_REPORT);
  }

  // 2. Walk .next/static/chunks/ for raw sizes
  const pages = {};

  if (fs.existsSync(NEXT_STATIC_CHUNKS)) {
    const files = fs.readdirSync(NEXT_STATIC_CHUNKS);
    console.log("Scanning", files.length, "files in", NEXT_STATIC_CHUNKS);

    for (const file of files) {
      if (!file.endsWith(".js") && !file.endsWith(".mjs")) continue;

      const filePath = path.join(NEXT_STATIC_CHUNKS, file);
      const stat = fs.statSync(filePath);

      // Determine if this is a page chunk
      if (isFrameworkChunk(file)) continue;

      if (!isPageChunk(file)) {
        // Also catch anything in a pages/ subdirectory
        if (!file.startsWith("pages/") && !file.includes("/pages/")) continue;
      }

      const pageName = extractPageName(file);
      const size = stat.size;

      if (pages[pageName]) {
        pages[pageName] += size;
      } else {
        pages[pageName] = size;
      }
    }
  } else {
    console.warn("Chunks directory not found at:", NEXT_STATIC_CHUNKS);
  }

  // 3. Fallback: use .bundle-report.json data if no page chunks found
  if (Object.keys(pages).length === 0 && bundleReport && bundleReport.bundles) {
    console.warn("Fallback: extracting from bundle report bundles.");
    for (const b of bundleReport.bundles) {
      const name = b.name || "";
      if (isFrameworkChunk(name)) continue;
      // Use raw size
      const sizeKB = parseFloat(b.size) || 0;
      const sizeBytes = sizeKB * 1024;
      const pageName = name.replace(/-[a-f0-9]{8,20}\./, ".").replace(/\.js$/, "");
      pages[pageName] = (pages[pageName] || 0) + sizeBytes;
    }
  }

  // 4. Compute totals
  const totalSize = Object.values(pages).reduce((sum, s) => sum + s, 0);
  const sizeKB = (totalSize / 1024).toFixed(1);

  console.log("");
  console.log("--- Bundle Sizes ---");
  console.log("Total JS (tracked pages):", sizeKB, "KB");
  console.log("Pages tracked:", Object.keys(pages).length);
  console.log("");

  // Sort by size descending
  const sorted = Object.entries(pages).sort((a, b) => b[1] - a[1]);
  for (const [page, size] of sorted) {
    console.log(`  ${page}: ${(size / 1024).toFixed(1)} KB`);
  }

  // 5. Write output (compact JSON for CI compatibility)
  const output = {
    pages,
    totalSize,
    generatedAt: new Date().toISOString(),
  };

  const json =
    process.env.CI === "true"
      ? JSON.stringify(output)
      : JSON.stringify(output, null, 2);

  const outPath = path.join(OUTPUT_DIR, "bundle-sizes.json");
  fs.writeFileSync(outPath, json, "utf8");
  console.log("\nOutput written to:", outPath);
}

main();
